import sys
from collections import defaultdict
def main():
    d = defaultdict(float)
    data = sys.stdin.buffer.read().split(b'\n')
    for line in data[1:]:
        if line:
            p = line.split(b',')
            d[p[1]] += float(p[2])
    for k in sorted(d):
        print("%s %.2f" % (k.decode(), d[k]))
main()

import sys
from collections import defaultdict
def main():
    d = defaultdict(list)
    data = sys.stdin.buffer.read().split(b'\n')
    for line in data[1:]:
        if line:
            a, b, c = line.split(b',')
            d[b].append(c)
    for k in sorted(d):
        print("%s %.2f" % (k.decode(), sum(map(float, d[k]))))
main()
